"""Flying creatures: independent anatomy, shared joins within each race."""
from .paths import ROOT
SOURCE = ROOT/'media/constructor/flyers/v5'
SPECIES = {
    'sky-dragon': ('Драконы', 'dragon_flight_authoring_v1', 'dragon'),
    'sky-bone-dragon': ('Скелетные драконы', 'dragon_flight_authoring_v1', 'bone-dragon'),
    'sky-eagle': ('Орлы', 'avian_flight_authoring_v1', 'eagle'),
}
CONTRACTS = {
 'dragon_flight_authoring_v1': ('head','torso','front_left_leg','front_right_leg','hind_left_leg','hind_right_leg','tail','left_wing','right_wing'),
 'avian_flight_authoring_v1': ('head','torso','left_wing','right_wing','left_leg','right_leg','tail'),
}
NAMES = {'dragon': ('Огненный дракон', 'Дракон ветров', 'Древний дракон'),
         'bone-dragon': ('Костяной страж', 'Дракон-некромант', 'Древний остов'),
         'eagle': ('Беркут', 'Белоголовый орлан', 'Гарпия')}
DESCRIPTIONS = {
    'dragon': 'Четвероногий дракон: рельефная грудная клетка, длинная шея, рептильный череп с надбровными гребнями, укоренённые зубы, когтистые лапы, хвост и две отдельные перепончатые крылья с плечом, локтем, запястьем и пятью пальцами.',
    'bone-dragon': 'Скелетный дракон: полый череп с открытыми глазницами, отдельная зубчатая нижняя челюсть, открытые рёбра и таз, цепь позвонков, суставные концы костей, четыре когтистые лапы и крылья с костными пальцами. Нет сплошного тела под рёбрами.',
    'eagle': 'Хищная птица: крючковатый клюв с восковицей и ноздрями, глубокие глаза под надбровьем, перья затылка, объёмная грудь, отдельные крылья с перекрывающимися маховыми и покровными перьями, хвостовой веер, мощные лапы и четыре загнутых когтя.',
}
DESIGNS = [dict(id=f'flyer-{kind}-{i+1:02d}', race=race, gender='male', variant=i,
                label=name, contract=contract, anatomy=kind, hair='cropped',
                description_ru=DESCRIPTIONS[kind])
           for race, (_, contract, kind) in SPECIES.items()
           for i, name in enumerate(NAMES[kind])]
IDS = {d['id'] for d in DESIGNS}


def part_description(design, slot):
    kind=design['anatomy'];base=design['label']+'. '
    if slot=='head':
        return base+({'dragon':'Рептильный череп, надбровные и скуловые гребни, укоренённые зубы, носовые отверстия, загнутые назад рога и шея.', 'bone-dragon':'Костный череп с открытыми глазницами и скуловыми дугами, верхняя и нижняя зубчатые челюсти, рога и шейные позвонки.', 'eagle':'Орлиная голова: непрерывный затылок, глубокие глаза под надбровьем, крючковатый клюв, восковица и ноздри, затылочные перья.'}[kind])
    if slot=='torso':
        return base+({'dragon':'Глубокая грудная клетка, лопаточная область, подобранный живот, поясница и круп; прилегающие грудные чешуйки и спинные гребни.', 'bone-dragon':'Открытая грудная клетка, дуги рёбер без сплошной оболочки, грудина, лопатки, позвоночник и открытый таз.', 'eagle':'Объёмная птичья грудь с килем, узкий живот, плечевой пояс и перекрывающиеся контурные перья.'}[kind])
    if slot.endswith('_wing'):
        return base+({'dragon':'Раскрытое крыло: плечо, локоть, запястье, пять опорных пальцев, большой коготь и замкнутые вогнутые лопасти перепонки.', 'bone-dragon':'Раскрытое костное крыло: плечевой сустав, плечевая и лучевая кости, запястье, длинные пальцы и фаланги. У некроманта сохраняются рваные остатки перепонки.', 'eagle':'Раскрытое перьевое крыло: плечо, локоть, запястье; раздельный веер первичных маховых, перекрывающиеся вторичные маховые и два ряда покровных перьев.'}[kind])
    if slot=='tail':
        return base+('Веер отдельных рулевых перьев, направленный назад.' if kind=='eagle' else 'Подвижная цепь хвостовых позвонков с костными отростками.' if kind=='bone-dragon' else 'Длинный сужающийся назад хвост с прилегающими гребнями.')
    return base+('Поджатая птичья лапа: бедро, согнутая цевка, чешуйки, три собранных передних пальца и противопоставленный задний палец с загнутыми когтями.' if kind=='eagle' else ('Передняя' if slot.startswith('front_') else 'Задняя')+' лапа поджата в полёте; '+('кости с расширенными суставными концами' if kind=='bone-dragon' else 'выраженные мышцы и суставы')+', запястье/скакательный сустав, пальцы и загнутые когти. Нет опоры на землю.')
